class Plus {
  transform(value: number) {
    return value + 1
  }
}
class Twice {
  transform(value: number) {
    return value * 2
  }
}
console.log(new Twice().transform(new Plus().transform(3)))

class Boom {
  transform(_value: number) {
    throw new BadRequestException()
  }
}
try {
  console.log(new Boom().transform(1))
} catch {
  console.log(0)
}

class Add {
  intercept(ctx, next) {
    return next.handle().pipe(map((v) => v + 1))
  }
}
@UseInterceptors(Add)
@Controller()
class C {
  @Get()
  run() {
    return 2
  }
}

