@Injectable()
class N {
  n = 5
}
@Injectable()
class Box {
  constructor(@Optional() private n?: N) {}
  read() {
    return this.n ? this.n.n : 0
  }
}
console.log(app.get(Box).read())

const TOKEN = 'N'
@Injectable()
class Box {
  constructor(@Inject(TOKEN) private n: number) {}
  read() {
    return this.n
  }
}
providers: [Box, { provide: TOKEN, useValue: 12 }]
console.log(app.get(Box).read())

